export type ServicePathway = "Build or improve your website" | "Improve visibility and measurement";

export type ServiceCatalogueEntry = {
  id: string;
  pathway: ServicePathway;
  serviceType: "website-project" | "website-feature" | "managed-service" | "support" | "consultation-review" | "implementation";
  title: string;
  description: string;
  price: string;
  websiteRedesignRequired: boolean;
  accessRequirement?: string;
  pricingPath?: string;
};

