export const serviceScopeBoundaries = businessFacts.serviceScopeBoundaries;
export const servicePages = businessFacts.servicePages;
export const serviceNavigation = servicePages.navigation;
export type ServicePageKey = Exclude<keyof typeof servicePages, "navigation">;
export const getServicePage = <Key extends ServicePageKey>(key: Key): (typeof servicePages)[Key] => servicePages[key];
export const getServiceBoundaries = (ids: readonly string[]) =>
  ids.map((id) => serviceScopeBoundaries.find((boundary) => boundary.id === id)).filter(Boolean);
